import { test as base, expect } from '@playwright/test';
import { apiResponse, dashboardData } from './data.js';

// Explicit opt-in only. This marker is scoped to the disposable browser context and prevents
// navigation/reload (or a second page) from overwriting snapshots generated by the app.
export async function seedVelocitySnapshot(page, snapshot) {
  await page.addInitScript((snapshot) => {
    const marker = '__e2e_home_velocity_seeded';
    if (localStorage.getItem(marker)) return;
    localStorage.setItem(
      'dev-dashboard.home-velocity.snapshot',
      JSON.stringify({ version: 2, snapshot }),
    );
    localStorage.setItem(marker, '1');
  }, snapshot);
}

export async function installDashboardMocks(context, baseURL, data = dashboardData()) {
  const requests = [];
  const unexpected = [];
  const pageErrors = [];
  context.on('page', (page) =>
    page.on('pageerror', (error) => pageErrors.push(`${error.message}\n${error.stack || ''}`)),
  );
  await context.route('**/*', async (route) => {
    const request = route.request();
    const url = new URL(request.url());
    const method = request.method();
    requests.push({ method, path: url.pathname + url.search });
    if (url.origin !== baseURL) {
      unexpected.push(`${method} ${url.href}`);
      await route.abort('blockedbyclient');
      return;
    }
    if (url.origin === baseURL) {
      const response = apiResponse(
        url,
        method,
        data,
        request.postData() ? request.postDataJSON() : undefined,
      );
      if (response) return route.fulfill(response);
      if (method === 'GET' && (url.pathname === '/' || url.pathname.startsWith('/assets/'))) {
        return route.continue();
      }
      if (url.pathname.startsWith('/api/')) {
        unexpected.push(`${method} ${url.href}`);
        await route.abort('blockedbyclient');
        return;
      }
      if (method === 'GET' && url.pathname === '/favicon.ico')
        return route.fulfill({ status: 204 });
    }
    unexpected.push(`${method} ${url.href}`);
    await route.abort('blockedbyclient');
  });
  await context.routeWebSocket('**/*', (socket) => {
    unexpected.push(`WebSocket ${socket.url()}`);
    socket.close();
  });
  await context.exposeBinding('__unexpectedDashboardNetwork', (_source, url) =>
    unexpected.push(url),
  );
  await context.exposeBinding('__devtoolsStreamClosed', () => {
    if (data.devtools) data.devtools.subscriptions = {};
  });
  await context.addInitScript(
    ({ services }) => {
      document.addEventListener('securitypolicyviolation', (event) => {
        window.__unexpectedDashboardNetwork(`CSP ${event.blockedURI}`);
      });
      const streams = [];
      const screencasts = [];
      const clipboard = { writes: [], error: null };
      class MockEventSource extends EventTarget {
        static CONNECTING = 0;
        static OPEN = 1;
        static CLOSED = 2;
        CONNECTING = 0;
        OPEN = 1;
        CLOSED = 2;
        constructor(url) {
          super();
          this.url = new URL(url, location.href).href;
          this.readyState = 0;
          this.onopen = null;
          this.onmessage = null;
          this.onerror = null;
          // The DevTools live view: ONE stream for the whole wall and the viewer, so a spec can
          // count them. Like the server it says its id first; a spec sends everything after that.
          const screencast =
            new URL(this.url).pathname === '/api/devtools/stream' &&
            new URL(this.url).origin === location.origin;
          if (this.url !== location.origin + '/api/events' && !screencast) {
            window.__unexpectedDashboardNetwork(`EventSource ${this.url}`);
            this.readyState = 2;
            return;
          }
          if (screencast) {
            this.screencast = true;
            screencasts.push(this);
            setTimeout(() => {
              this.emit('open');
              this.emit('hello', {
                stream: `e2e-stream-${String(screencasts.length).padStart(8, '0')}`,
              });
            }, 0);
            return;
          }
          streams.push(this);
          setTimeout(() => {
            if (this.readyState === 2) return;
            this.emit('open');
            this.emit('message', services);
          }, 0);
        }
        emit(type, snapshot) {
          if (this.readyState === 2) return;
          if (type === 'open') this.readyState = 1;
          if (type === 'error') this.readyState = 0;
          const event = [
            'message',
            'setup-required',
            'hello',
            'frame',
            'status',
            'target',
            'tabs',
          ].includes(type)
            ? new MessageEvent(type, { data: JSON.stringify(snapshot) })
            : new Event(type);
          this.dispatchEvent(event);
          this['on' + type]?.(event);
        }
        close() {
          // Closing the live-view stream is what makes the server let go of everything it held.
          if (this.screencast && this.readyState !== 2)
            Promise.resolve(window.__devtoolsStreamClosed()).catch(() => {});
          this.readyState = 2;
        }
      }
      window.EventSource = MockEventSource;
      Object.defineProperty(navigator, 'clipboard', {
        configurable: true,
        value: {
          async writeText(text) {
            if (clipboard.error) throw new Error(clipboard.error);
            clipboard.writes.push(text);
          },
          async readText() {
            return clipboard.writes.at(-1) || '';
          },
        },
      });
      window.__dashboardMock = { streams, screencasts, clipboard };
    },
    { services: data.services },
  );
  return { data, requests, unexpected, pageErrors };
}

// What the page asked the mocked Slack API for, read off the recorded requests.
export const listReads = ({ requests }) =>
  requests.filter(({ method, path }) => method === 'GET' && path.startsWith('/api/slack/threads'));
export const watchRequests = ({ requests }) =>
  requests.filter(({ path }) => path.startsWith('/api/slack/watch'));
export const watchListReads = (dashboard) =>
  watchRequests(dashboard).filter(
    ({ method, path }) => method === 'GET' && path === '/api/slack/watch',
  );

export const test = base.extend({
  dashboardFixture: [null, { option: true }],
  dashboard: [
    async ({ context, baseURL, dashboardFixture }, use) => {
      // `{ build }` makes the data afresh for each test, so one that changes it cannot leak into the next.
      const data = dashboardFixture?.build
        ? dashboardFixture.build()
        : dashboardFixture || dashboardData();
      const mock = await installDashboardMocks(context, baseURL, data);
      await use(mock);
      expect(mock.unexpected, 'Unexpected network was blocked').toEqual([]);
      expect(mock.pageErrors, 'Browser runtime errors').toEqual([]);
    },
    { auto: true },
  ],
});

export { expect };
